}
```

```ts
import { IResponse, IStatement } from ".."

export interface IEntry {
  id: string
  conversations: IConversation[]
}

export interface IConversation {
  from: "human" | "gpt"
  value: string
}

export function parse(input: string): IEntry[] {
  const json = JSON.parse(input) as { [key: string]: any }[]
  return json.map((entry: { [key: string]: any }) => {
    const conversations = entry.conversations.map(
      (conv: { [key: string]: any }) => {
        return {
          from: conv.from,
          value: conv.value,
        } as IConversation
      }
    )
    return {
      id: entry.id,
      conversations: conversations,
    } as IEntry
  })
}

export function respond(
  input: string,
  entries: IEntry[],
  statement: IStatement
): IResponse {
  const id = statement.id
  const entry = entries.find((e) => e.id === id)
  if (!entry) {
    return {
      type: "error",
      value: `Entry not found: ${id}`,
    }
  }
  const conversation = entry.conversations.find(
    (c) => c.from === "human" && c.value === input
  )
  if (!conversation) {
    return {
      type: "error",
      value: `Conversation not found: ${input}`,
    }
  }
  const response = entry.conversations.find(
    (c) => c.from === "gpt" && conversation && conversation.value === c.value
  )
  if (!response) {
    return {
      type: "error",
      value: `Response not found for: ${conversation.value}`,
    }
  }
  return {
    type: "success",
    value: response.value,
  }
}
```

